<?php
namespace App\Foundation\Console;use App\Foundation\Registry\ProjectRegistry;use Illuminate\Console\Command;
final class NavigationCheckCommand extends Command{protected $signature='navigation:check';protected $description='Check navigation route names and permissions against manifests.';public function handle(ProjectRegistry $r):int{$routes=array_column($r->pages(),'route_name');$perms=$r->permissions();$bad=false;foreach($r->navigation() as $s=>$items){foreach($items as $i){if(!in_array($i['route']??'',$routes,true)){$this->error("{$s}: missing page route ".($i['route']??''));$bad=true;}if(($i['permission']??null)&&!in_array($i['permission'],$perms,true)){$this->error("{$s}: missing permission {$i['permission']}");$bad=true;}}}if(!$bad)$this->info('Navigation valid.');return $bad?self::FAILURE:self::SUCCESS;}}
